<style>
  :root{--module-ink:#17211b;--module-muted:#68756d;--module-border:#dde5df;--module-soft:#f6f8f6;--module-green:#17643a;--module-green-dark:#10532f;--module-green-soft:#e7f3eb;--module-blue:#2b68a7;--module-blue-soft:#eaf2fa;--module-amber:#9a650e;--module-amber-soft:#faf1dc;--module-red:#b33a3a;--module-red-soft:#faeaea}
  .module-page{display:flex;flex-direction:column;gap:16px;color:var(--module-ink)}
