  .module-eyebrow{display:flex;align-items:center;gap:7px;color:var(--module-green);font-size:10px;font-weight:900;letter-spacing:.075em;text-transform:uppercase}.module-eyebrow:before{content:"";width:7px;height:7px;border-radius:50%;background:#42a363;box-shadow:0 0 0 4px rgba(66,163,99,.12)}
  .module-header h1{margin:7px 0 4px;color:var(--module-ink);font-size:clamp(25px,3vw,34px);line-height:1.08;font-weight:850;letter-spacing:-.035em}.module-header p{max-width:680px;margin:0;color:var(--module-muted);font-size:12px;line-height:1.5}.module-actions{display:flex;justify-content:flex-end;gap:8px;flex-wrap:wrap}
  .module-button{display:inline-flex;align-items:center;justify-content:center;gap:7px;min-height:38px;padding:8px 12px;border:1px solid var(--module-border);border-radius:8px;color:#34443a;background:#fff;font-size:11px;font-weight:850;text-decoration:none;cursor:pointer;transition:.15s ease}.module-button svg{width:15px;height:15px;fill:none;stroke:currentColor;stroke-width:1.9;stroke-linecap:round;stroke-linejoin:round}.module-button:hover{color:var(--module-green);border-color:#a5bbad;background:#f9fbf9}.module-button-primary{color:#fff;border-color:var(--module-green);background:var(--module-green)}.module-button-primary:hover{color:#fff;border-color:var(--module-green-dark);background:var(--module-green-dark)}.module-button-danger{color:var(--module-red);border-color:#efcaca;background:#fff}.module-button-danger:hover{color:#982f2f;border-color:#e5aaaa;background:#fff7f7}.module-button-small{min-height:30px;padding:5px 8px;font-size:9px}
  .module-alert{padding:11px 13px;border:1px solid var(--successBorder);border-radius:9px;color:var(--successText);background:var(--successBg);font-size:11px;font-weight:700}.module-alert-error{color:var(--dangerText);border-color:var(--dangerBorder);background:var(--dangerBg)}.module-alert ul{margin:6px 0 0 18px;padding:0}
  .module-kpis{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:11px}.module-kpi{min-width:0;padding:15px 16px;border:1px solid var(--module-border);border-radius:10px;background:#fff;box-shadow:0 2px 8px rgba(20,40,27,.025)}.module-kpi-top{display:flex;align-items:center;justify-content:space-between;gap:8px}.module-kpi-label{color:var(--module-muted);font-size:9px;font-weight:900;letter-spacing:.055em;text-transform:uppercase}.module-kpi-icon{width:29px;height:29px;display:grid;place-items:center;border-radius:7px;color:var(--module-green);background:var(--module-green-soft)}.module-kpi-icon svg{width:15px;height:15px;fill:none;stroke:currentColor;stroke-width:1.9;stroke-linecap:round;stroke-linejoin:round}.module-kpi-icon-blue{color:var(--module-blue);background:var(--module-blue-soft)}.module-kpi-icon-amber{color:var(--module-amber);background:var(--module-amber-soft)}.module-kpi-icon-red{color:var(--module-red);background:var(--module-red-soft)}.module-kpi strong{display:block;margin:13px 0 5px;color:var(--module-ink);font-size:25px;line-height:1;font-weight:850;letter-spacing:-.03em}.module-kpi strong small{font-size:11px;letter-spacing:0;color:var(--module-muted)}.module-kpi>small{display:block;overflow:hidden;color:var(--module-muted);font-size:9px;line-height:1.35;text-overflow:ellipsis;white-space:nowrap}
