  .module-table-tools{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:12px 15px;border-bottom:1px solid var(--module-border);background:#fff}.module-table-tools strong{color:var(--module-ink);font-size:12px}.module-table-tools span{display:block;margin-top:2px;color:var(--module-muted);font-size:9px}.module-table-scroll{overflow:auto}.module-table{width:100%;min-width:960px;border-collapse:collapse}.module-table th{padding:10px 12px;border-bottom:1px solid var(--module-border);color:var(--module-muted);background:#f8faf8;font-size:9px;font-weight:900;letter-spacing:.045em;text-align:left;text-transform:uppercase;white-space:nowrap}.module-table td{padding:12px;border-bottom:1px solid #edf1ee;color:#435047;font-size:10px;vertical-align:middle}.module-table tbody tr:last-child td{border-bottom:0}.module-table tbody tr:not(.module-detail-row):hover td{background:#fbfcfb}.module-table td strong{color:var(--module-ink);font-weight:800}.module-table td small{display:block;margin-top:3px;color:var(--module-muted);font-size:9px;line-height:1.35}.module-table .module-numeric{text-align:right}.module-person{display:flex;align-items:center;gap:9px;min-width:190px}.module-avatar{width:31px;height:31px;display:grid;place-items:center;flex:0 0 auto;border-radius:8px;color:#fff;background:#285a3b;font-size:9px;font-weight:900}.module-person-copy{min-width:0}.module-person-copy strong,.module-person-copy small{display:block;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.module-mono{font-family:ui-monospace,SFMono-Regular,Menlo,Consolas,monospace!important}.module-badge{display:inline-flex;align-items:center;min-height:21px;padding:3px 7px;border-radius:999px;color:#526057;background:#edf1ee;font-size:8px;font-weight:850;white-space:nowrap}.module-badge-green{color:var(--module-green);background:var(--module-green-soft)}.module-badge-blue{color:var(--module-blue);background:var(--module-blue-soft)}.module-badge-amber{color:var(--module-amber);background:var(--module-amber-soft)}.module-badges{display:flex;gap:4px;flex-wrap:wrap}.module-row-actions{display:flex;justify-content:flex-end;gap:5px;white-space:nowrap}.module-detail-row td{padding:0;background:#f8faf8}.module-detail-row[hidden]{display:none}.module-detail-grid{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:0;padding:5px 12px 12px}.module-detail-grid div{min-width:0;padding:10px;border-right:1px solid #e4eae6;border-bottom:1px solid #e4eae6}.module-detail-grid div:nth-child(5n){border-right:0}.module-detail-grid dt{color:var(--module-muted);font-size:8px;font-weight:850;letter-spacing:.04em;text-transform:uppercase}.module-detail-grid dd{margin:4px 0 0;overflow-wrap:anywhere;color:var(--module-ink);font-size:10px;font-weight:750}.module-empty{display:flex;flex-direction:column;align-items:center;justify-content:center;min-height:180px;padding:28px;text-align:center}.module-empty-icon{width:44px;height:44px;display:grid;place-items:center;margin-bottom:10px;border-radius:12px;color:var(--module-green);background:var(--module-green-soft)}.module-empty-icon svg{width:21px;height:21px;fill:none;stroke:currentColor;stroke-width:1.8}.module-empty strong{color:var(--module-ink);font-size:12px}.module-empty span{max-width:360px;margin:5px 0 12px;color:var(--module-muted);font-size:10px;line-height:1.5}
