  .module-pagination{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:10px 15px;border-top:1px solid var(--module-border);background:#fff}.module-pagination-meta{color:var(--module-muted);font-size:9px}.module-pagination .agri-pagination{margin-left:auto!important}.module-pagination a,.module-pagination span{box-shadow:none}.module-pagination svg{width:14px;height:14px}
  .module-form-shell{display:grid;grid-template-columns:minmax(0,1fr) 270px;gap:15px;align-items:start}.module-form-main{display:flex;flex-direction:column;gap:13px}.module-form-section{overflow:hidden;border:1px solid var(--module-border);border-radius:11px;background:#fff}.module-form-section-head{display:flex;align-items:flex-start;gap:11px;padding:14px 16px;border-bottom:1px solid var(--module-border);background:#fbfcfb}.module-step{width:26px;height:26px;display:grid;place-items:center;flex:0 0 auto;border-radius:7px;color:#fff;background:var(--module-green);font-size:10px;font-weight:900}.module-form-section-head h2{margin:0;color:var(--module-ink);font-size:14px;font-weight:850}.module-form-section-head p{margin:3px 0 0;color:var(--module-muted);font-size:9px;line-height:1.4}.module-form-body{padding:16px}.module-form-grid{display:grid;grid-template-columns:repeat(6,minmax(0,1fr));gap:12px}.module-form-field{grid-column:span 3;min-width:0}.module-form-field-third{grid-column:span 2}.module-form-field-full{grid-column:1/-1}.module-form-field label{display:block;margin:0 0 6px;color:#45534a;font-size:10px;font-weight:850}.module-required{color:var(--module-red)}.module-hint{margin-top:5px;color:var(--module-muted);font-size:9px;line-height:1.4}.module-form-aside{position:sticky;top:16px;display:flex;flex-direction:column;gap:12px}.module-aside-card{padding:14px;border:1px solid var(--module-border);border-radius:10px;background:#fff}.module-aside-card h3{margin:0 0 8px;color:var(--module-ink);font-size:11px;font-weight:850}.module-aside-card p,.module-aside-card li{color:var(--module-muted);font-size:9px;line-height:1.5}.module-aside-card p{margin:0}.module-aside-card ol,.module-aside-card ul{margin:0;padding-left:17px}.module-aside-card li+li{margin-top:5px}.module-form-actions{display:flex;align-items:center;justify-content:flex-end;gap:8px;padding:13px 16px;border-top:1px solid var(--module-border);background:#fbfcfb}.module-preview-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:8px;margin-top:13px}.module-preview-item{min-width:0;padding:10px;border:1px solid #e3e9e5;border-radius:8px;background:#fbfcfb}.module-preview-item-wide{grid-column:span 3}.module-preview-item span{display:block;color:var(--module-muted);font-size:8px;font-weight:850;letter-spacing:.04em;text-transform:uppercase}.module-preview-item strong{display:block;margin-top:4px;overflow:hidden;color:var(--module-ink);font-size:10px;text-overflow:ellipsis;white-space:nowrap}.module-dropzone{display:flex;align-items:center;gap:13px;padding:18px;border:1px dashed #9eb1a5;border-radius:9px;background:#f9fbf9}.module-dropzone-icon{width:40px;height:40px;display:grid;place-items:center;flex:0 0 auto;border-radius:9px;color:var(--module-green);background:var(--module-green-soft)}.module-dropzone-icon svg{width:20px;height:20px;fill:none;stroke:currentColor;stroke-width:1.8}.module-dropzone input{width:100%;font-size:10px}
  @media(max-width:1180px){.module-kpis{grid-template-columns:repeat(2,minmax(0,1fr))}.module-form-shell{grid-template-columns:1fr}.module-form-aside{position:static;display:grid;grid-template-columns:repeat(2,minmax(0,1fr))}.module-detail-grid{grid-template-columns:repeat(3,minmax(0,1fr))}.module-detail-grid div:nth-child(5n){border-right:1px solid #e4eae6}.module-detail-grid div:nth-child(3n){border-right:0}}
  @media(max-width:820px){.module-header{align-items:flex-start;flex-direction:column}.module-actions{justify-content:flex-start}.module-filter-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.module-field,.module-field-wide,.module-field-search{grid-column:span 1}.module-field-search{grid-column:1/-1}.module-analytics-grid{grid-template-columns:1fr}.module-chart-body{height:230px}.module-form-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.module-form-field,.module-form-field-third{grid-column:span 1}.module-form-field-full{grid-column:1/-1}}
  @media(max-width:560px){.module-header{padding:15px}.module-actions,.module-actions .module-button{width:100%}.module-kpis,.module-filter-grid{grid-template-columns:1fr}.module-field,.module-field-wide,.module-field-search{grid-column:1/-1}.module-filter-actions{align-items:flex-start;flex-direction:column}.module-filter-buttons,.module-filter-buttons .module-button{width:100%}.module-form-grid,.module-form-aside,.module-preview-grid{grid-template-columns:1fr}.module-form-field,.module-form-field-third,.module-form-field-full,.module-preview-item-wide{grid-column:1}.module-form-actions{align-items:stretch;flex-direction:column-reverse}.module-form-actions .module-button{width:100%}.module-detail-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.module-detail-grid div:nth-child(3n){border-right:1px solid #e4eae6}.module-detail-grid div:nth-child(2n){border-right:0}.module-pagination{align-items:flex-start;flex-direction:column}.module-pagination nav{margin-left:0;width:100%}}
</style>
